<?php require __DIR__.'/_layout_start.php'; ?><style>#event-category-custom-wrap{display:none!important}label:has(#event-category option[value="Altro"]:checked)+#event-category-custom-wrap{display:block!important}</style><div class="toolbar"><div><h1><?= (int)$event['id']?'Modifica evento':'Nuovo evento' ?></h1><p class="muted">Contenuti, programma, disponibilità e pubblicazione.</p></div><a href="/idemaclima/admin/campus/events">Torna agli eventi</a></div><?php foreach($errors as $err):?><div class="error"><?= htmlspecialchars($err,ENT_QUOTES,'UTF-8') ?></div><?php endforeach;?><form method="post" action="/idemaclima/admin/campus/events/save" class="panel" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf,ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int)$event['id'] ?>"><div class="formgrid"><label>Titolo<input name="title" maxlength="220" required value="<?= htmlspecialchars((string)$event['title'],ENT_QUOTES,'UTF-8') ?>"></label><label>Slug<input name="slug" maxlength="240" value="<?= htmlspecialchars((string)$event['slug'],ENT_QUOTES,'UTF-8') ?>"></label><label>Tipologia<select name="audience"><option value="public" <?= $event['audience']==='public'?'selected':'' ?>>Evento aperto</option><option value="cat" <?= $event['audience']==='cat'?'selected':'' ?>>Evento CAT</option></select></label><?php $eventCategoryOptions=['Residenziale','Commerciale','Sistemi industriali','Pompe di calore'];$currentEventCategory=(string)($event['category']??'');$selectedEventCategory=in_array($currentEventCategory,$eventCategoryOptions,true)?$currentEventCategory:($currentEventCategory!==''?'Altro':''); ?><label>Categoria<select name="category_choice" id="event-category" required><option value="">Seleziona una categoria</option><?php foreach($eventCategoryOptions as $categoryOption):?><option value="<?= htmlspecialchars($categoryOption,ENT_QUOTES,'UTF-8') ?>" <?= $selectedEventCategory===$categoryOption?'selected':'' ?>><?= htmlspecialchars($categoryOption,ENT_QUOTES,'UTF-8') ?></option><?php endforeach;?><option value="Altro" <?= $selectedEventCategory==='Altro'?'selected':'' ?>>Altro</option></select></label><label id="event-category-custom-wrap" style="<?= $selectedEventCategory==='Altro'?'':'display:none' ?>">Categoria personalizzata<input name="category_custom" id="event-category-custom" maxlength="120" value="<?= $selectedEventCategory==='Altro'?htmlspecialchars($currentEventCategory,ENT_QUOTES,'UTF-8'):'' ?>" placeholder="Scrivi la categoria"></label><label>Luogo<input name="location" maxlength="190" value="<?= htmlspecialchars((string)$event['location'],ENT_QUOTES,'UTF-8') ?>"></label><label>Indirizzo<input name="address" maxlength="255" value="<?= htmlspecialchars((string)$event['address'],ENT_QUOTES,'UTF-8') ?>"></label><label>Inizio<input type="datetime-local" name="starts_at" required value="<?= !empty($event['starts_at'])?htmlspecialchars(str_replace(' ','T',substr((string)$event['starts_at'],0,16)),ENT_QUOTES,'UTF-8'):'' ?>"></label><label>Fine<input type="datetime-local" name="ends_at" value="<?= !empty($event['ends_at'])?htmlspecialchars(str_replace(' ','T',substr((string)$event['ends_at'],0,16)),ENT_QUOTES,'UTF-8'):'' ?>"></label><label>Posti massimi<input type="number" min="1" name="max_seats" value="<?= htmlspecialchars((string)$event['max_seats'],ENT_QUOTES,'UTF-8') ?>"></label><label>Scadenza iscrizioni<input type="datetime-local" name="registration_deadline" value="<?= !empty($event['registration_deadline'])?htmlspecialchars(str_replace(' ','T',substr((string)$event['registration_deadline'],0,16)),ENT_QUOTES,'UTF-8'):'' ?>"></label><label>Quota evento (€)<input type="number" min="0" step="0.01" name="fee_amount" value="<?= htmlspecialchars((string)($event['fee_amount']??''),ENT_QUOTES,'UTF-8') ?>" placeholder="Lascia vuoto se gratuito"></label><label>Nota quota<input name="fee_note" maxlength="255" value="<?= htmlspecialchars((string)($event['fee_note']??''),ENT_QUOTES,'UTF-8') ?>" placeholder="Es. Rimborsabile sul successivo ordine"></label><label class="full">Copertina evento<input type="file" name="cover_image_file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG o WebP, massimo 8 MB.<?php if(!empty($event['cover_image'])): ?> Immagine attuale: <a href="<?= htmlspecialchars((string)$event['cover_image'],ENT_QUOTES,'UTF-8') ?>" target="_blank" rel="noopener">visualizza</a>.<?php endif; ?></small></label><label class="full">Descrizione breve<textarea name="short_description" maxlength="1000"><?= htmlspecialchars((string)$event['short_description'],ENT_QUOTES,'UTF-8') ?></textarea></label><label>Relatore / referente<input name="speaker" maxlength="190" value="<?= htmlspecialchars((string)($event['speaker']??''),ENT_QUOTES,'UTF-8') ?>"></label><label>Ordine<input type="number" name="sort_order" value="<?= (int)$event['sort_order'] ?>"></label><label class="full">Descrizione completa<textarea name="description" rows="7"><?= htmlspecialchars((string)$event['description'],ENT_QUOTES,'UTF-8') ?></textarea></label><label class="full">Programma / sessioni<textarea name="program" rows="7" placeholder="Una voce per riga"><?= htmlspecialchars((string)($event['program']??''),ENT_QUOTES,'UTF-8') ?></textarea></label><label class="check"><input type="checkbox" name="registration_open" value="1" <?= (int)$event['registration_open']?'checked':'' ?>> Iscrizioni aperte</label><label class="check"><input type="checkbox" name="waitlist_enabled" value="1" <?= (int)($event['waitlist_enabled']??1)?'checked':'' ?>> Lista d’attesa attiva</label><label class="check"><input type="checkbox" name="published" value="1" <?= (int)$event['published']?'checked':'' ?>> Pubblicato</label><label class="check"><input type="checkbox" name="cancelled" value="1" <?= (int)$event['cancelled']?'checked':'' ?>> Annullato</label></div><button class="btn" type="submit" style="margin-top:18px">Salva evento</button></form><script>(function(){const select=document.getElementById('event-category');const wrap=document.getElementById('event-category-custom-wrap');const input=document.getElementById('event-category-custom');function updateCustomCategory(){const custom=select.value==='Altro';wrap.style.display=custom?'':'none';input.required=custom;if(!custom)input.value='';}select.addEventListener('change',updateCustomCategory);updateCustomCategory();})();</script><?php require __DIR__.'/_layout_end.php'; ?>
